      if (!items.length) s.insertAdjacentHTML('beforeend', '<div class="saved-empty">' + (clearKey ? 'Documents you open will appear here.' : 'Press the star on any page to keep it here for quick access.') + '</div>');
      var list = document.createElement('div'); list.className = 'list';
