      if (fav.length) h += '<div class="sec-title"><h2>Pick up where you left off</h2><span>Favourites &amp; recent</span></div><div class="cards">' +
        fav.map(function (x) { var n = S.byKey[x.key]; return '<button class="card" data-go="' + esc(n.key) + '"><div class="card-top"><div class="ci">' + ic('file') + '</div><h3>' + esc(n.title) + '</h3></div><div class="meta"><span>' + esc(n.showCode ? n.code : VIEWS[n.view].name) + '</span><span>' + (S.favs.some(function (f) { return f.key === n.key; }) ? '★ Saved' : 'Recent') + '</span></div></button>'; }).join('') + '</div>';
      h += '<div class="sec-title"><h2>Modules</h2><span>Choose a module to explore its documents</span></div><div class="cards">' +
        M.map(function (m) { return '<button class="card big" data-go="' + esc(m.key) + '"><div class="card-top"><div class="ci gold">' + ic('folder') + '</div><h3>' + esc(m.title) + '</h3><span class="abbr">' + esc(m.abbr) + '</span></div><div class="meta"><span>' + m.children.length + ' groups</span><span>' + (m.total ? m.total + ' documents' : 'Coming soon') + '</span></div></button>'; }).join('') + '</div>';
